function openMenu(){classie.has(header,"hamburger")||classie.has(header,"search")?(classie.add(header,"header-menu-open"),classie.add(menu,"open")):(classie.remove(header,"header-menu-open"),classie.remove(menu,"open"))}function showMenu(){classie.remove(header,"search"),classie.remove(menu_searchMenu,"active"),classie.toggleClass(header,"hamburger"),classie.toggleClass(menu_mainMenu,"active")}function showSearch(){classie.remove(header,"hamburger"),classie.remove(menu_mainMenu,"active"),classie.toggleClass(header,"search"),classie.toggleClass(menu_searchMenu,"active")}function searchFocus(){classie.has(header,"header-menu-open")?setTimeout(function(){searchInput.focus()},500):searchInput.blur()}function getPos(e){for(var n=0,a=0;null!=e;n+=e.offsetLeft,a+=e.offsetTop,e=e.offsetParent);return{x:n,y:a}}function getHeight(e){return $(e)[0].offsetHeight}var header=document.getElementsByTagName("header")[0],menu=document.getElementById("menu"),hamburgerMenu=document.getElementById("hamburgerMenu"),searchMenu=document.getElementById("searchMenu"),searchInput=document.getElementById("searchInput"),menu_mainMenu=document.querySelector(".main-menu"),menu_searchMenu=document.querySelector(".search-menu");hamburgerMenu.onclick=function(){showMenu(),openMenu()},searchMenu.onclick=function(){showSearch(),openMenu(),searchFocus()};